125	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
126	    @Override
127	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
128	        validateRequiredFields(ownerFieldsDto);
129	        HttpHeaders headers = new HttpHeaders();
130	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
131	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
132	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
133	            joinHousehold(owner);
134	        } else {
135	            requireUniqueHousehold(owner.getLastName(), owner.getAddress());
136	        }
137	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
138	        requireUniqueTelephone(telephone);
139	        owner.setTelephone(telephone);
140	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
141	        owner.setCustomerCode(generateCustomerCode(owner.getLastName()));
142	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
143	        this.clinicService.saveOwner(owner);
144	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
145	        headers.setLocation(UriComponentsBuilder.newInstance()
146	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
147	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
148	    }
